-- Rolled-back hosted SQL/RLS canary. All temporary identities and activity roll back.
BEGIN;
CREATE TEMP TABLE monitoring_canary_ids(kind text PRIMARY KEY,id uuid,email text);
INSERT INTO monitoring_canary_ids SELECT 'admin',id,email FROM auth.users WHERE lower(email)='riverabenlor461@gmail.com';
INSERT INTO monitoring_canary_ids SELECT kind,gen_random_uuid(),'edupulse-monitor-canary-'||gen_random_uuid()::text||'@example.invalid' FROM unnest(ARRAY['instructor','learner','outsider']) kind;
GRANT SELECT ON monitoring_canary_ids TO authenticated;
CREATE FUNCTION pg_temp.monitoring_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF NOT coalesce(ok,false) THEN RAISE EXCEPTION 'Monitoring canary failed: %',label; END IF; END $$;
CREATE FUNCTION pg_temp.monitoring_as(account text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
 PERFORM set_config('request.jwt.claim.sub',(SELECT id::text FROM monitoring_canary_ids WHERE kind=account),true);
 PERFORM set_config('request.jwt.claims',(SELECT jsonb_build_object('sub',id,'email',email,'role','authenticated','app_metadata',jsonb_build_object('role',CASE WHEN kind='admin' THEN 'admin' WHEN kind='learner' THEN 'student' ELSE 'instructor' END))::text FROM monitoring_canary_ids WHERE kind=account),true);
END $$;
SELECT pg_temp.monitoring_assert((SELECT count(*)=4 FROM monitoring_canary_ids),'verified owner admin exists');
INSERT INTO auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
 SELECT '00000000-0000-0000-0000-000000000000',id,'authenticated','authenticated',email,'',now(),jsonb_build_object('role',CASE WHEN kind='learner' THEN 'student' ELSE 'instructor' END,'provider','email','providers',jsonb_build_array('email')),jsonb_build_object('full_name','Synthetic monitoring '||kind),now(),now() FROM monitoring_canary_ids WHERE kind<>'admin';
CREATE TEMP TABLE monitoring_canary_state(data jsonb,revision bigint);
INSERT INTO monitoring_canary_state VALUES($snapshot${"syllabi": [{"id": "monitoring-canary", "courseCode": "SYN-MONITOR", "courseTitle": "Synthetic monitoring class", "status": "active", "approvedFile": {"approvalAttested": true}, "courseOutline": [{"week": 1, "ilos": "Explain variables.", "contents": ["Variables"]}]}], "content": {"m": {"syllabusId": "monitoring-canary", "week": 1, "type": "material", "status": "checked", "content": {"title": "Synthetic monitoring lesson", "sections": [{"heading": "First", "body": "Original canary text."}, {"heading": "Last", "body": "Original final canary text."}]}}, "q": {"syllabusId": "monitoring-canary", "week": 1, "type": "assessment", "status": "checked", "content": {"title": "Synthetic monitoring quiz", "questions": [{"text": "Canary question 1", "options": ["A", "B", "C", "D"], "correctIndex": 0}, {"text": "Canary question 2", "options": ["A", "B", "C", "D"], "correctIndex": 1}, {"text": "Canary question 3", "options": ["A", "B", "C", "D"], "correctIndex": 2}]}}}, "registrations": [], "enrollmentOverrides": []}$snapshot$::jsonb,0);
UPDATE monitoring_canary_state SET data=jsonb_set(data,'{registrations}',jsonb_build_array(jsonb_build_object('id','canary-roster','courseCode','SYN-MONITOR','blockSection','SYN-1A','status','active','uploadedBy',(SELECT id::text FROM monitoring_canary_ids WHERE kind='instructor'),'students',jsonb_build_array(jsonb_build_object('Name','Synthetic monitoring learner','StudentID','CANARY','YearLevel','1','Email',(SELECT email FROM monitoring_canary_ids WHERE kind='learner'))))));
CREATE TEMP TABLE monitoring_canary_publications(id text,source_version text,type text);
CREATE TEMP TABLE monitoring_canary_session(id uuid);
GRANT SELECT,UPDATE ON monitoring_canary_state TO authenticated;
GRANT SELECT,INSERT ON monitoring_canary_publications,monitoring_canary_session TO authenticated;
SET LOCAL ROLE authenticated;
SELECT pg_temp.monitoring_as('instructor');
SELECT public.edupulse_save_workspace(0,data) FROM monitoring_canary_state;
UPDATE monitoring_canary_state SET revision=1,data=jsonb_set(jsonb_set(data,'{content,m,status}','"published"'),'{content,q,status}','"published"');
SELECT public.edupulse_save_workspace(1,data) FROM monitoring_canary_state;
INSERT INTO monitoring_canary_publications SELECT id,source_version,type FROM public.edupulse_publications;
SELECT pg_temp.monitoring_assert((SELECT count(*)=2 FROM monitoring_canary_publications),'reviewed canary material and assessment projected');
SELECT pg_temp.monitoring_as('learner');
SELECT public.edupulse_academic_action(id,source_version,'[]','open') FROM monitoring_canary_publications WHERE type='material';
DO $$ BEGIN BEGIN PERFORM public.edupulse_read_material_section(id,source_version,1) FROM monitoring_canary_publications WHERE type='material'; RAISE EXCEPTION 'Skipped section accepted'; EXCEPTION WHEN invalid_parameter_value THEN NULL; END; END $$;
SELECT public.edupulse_read_material_section(id,source_version,0) FROM monitoring_canary_publications WHERE type='material';
SELECT public.edupulse_read_material_section(id,source_version,0) FROM monitoring_canary_publications WHERE type='material';
SELECT pg_temp.monitoring_assert((SELECT sections_read=1 FROM public.edupulse_material_progress),'duplicate confirmation is idempotent');
SELECT public.edupulse_read_material_section(id,source_version,1) FROM monitoring_canary_publications WHERE type='material';
SELECT pg_temp.monitoring_assert((SELECT sections_read=total_sections AND completed_at IS NOT NULL FROM public.edupulse_material_progress),'real sequential completion persisted');
INSERT INTO monitoring_canary_session SELECT (public.edupulse_assessment_command(jsonb_build_object('operation','start','publication',id,'version',source_version))->>'id')::uuid FROM monitoring_canary_publications WHERE type='assessment';
SELECT public.edupulse_assessment_command(jsonb_build_object('operation','submit','publication',id,'version',source_version,'session',(SELECT id FROM monitoring_canary_session),'responses','[0,1,2]'::jsonb)) FROM monitoring_canary_publications WHERE type='assessment';
SELECT pg_temp.monitoring_as('instructor');
SELECT pg_temp.monitoring_assert((SELECT student_email=(SELECT email FROM monitoring_canary_ids WHERE kind='learner') FROM public.edupulse_assessment_sessions),'session metadata scoped to instructor');
UPDATE monitoring_canary_state SET revision=2,data=jsonb_set(data,'{enrollmentOverrides}',jsonb_build_array(jsonb_build_object('courseCode','SYN-MONITOR','studentEmail',(SELECT email FROM monitoring_canary_ids WHERE kind='learner'),'blockSection','SYN-1A','excluded',true,'suspended',true)));
DO $$ BEGIN BEGIN PERFORM public.edupulse_save_workspace(2,data) FROM monitoring_canary_state; RAISE EXCEPTION 'Active membership removal accepted'; EXCEPTION WHEN invalid_parameter_value THEN NULL; END; END $$;
UPDATE monitoring_canary_state SET data=jsonb_set(data,'{enrollmentOverrides,0,excluded}','false');
SELECT public.edupulse_save_workspace(2,data) FROM monitoring_canary_state;
SELECT pg_temp.monitoring_assert((SELECT suspended FROM public.edupulse_enrollments),'suspension persisted');
SELECT pg_temp.monitoring_as('learner');
SELECT pg_temp.monitoring_assert((SELECT count(*)=0 FROM public.edupulse_publications),'suspension hides released publications');
DO $$ BEGIN BEGIN PERFORM public.edupulse_academic_action(id,source_version,'[]','open') FROM monitoring_canary_publications WHERE type='material'; RAISE EXCEPTION 'Suspended open accepted'; EXCEPTION WHEN insufficient_privilege THEN NULL; END; END $$;
DO $$ BEGIN BEGIN PERFORM public.edupulse_read_material_section(id,source_version,0) FROM monitoring_canary_publications WHERE type='material'; RAISE EXCEPTION 'Suspended progress accepted'; EXCEPTION WHEN insufficient_privilege THEN NULL; END; END $$;
SELECT pg_temp.monitoring_as('outsider');
SELECT pg_temp.monitoring_assert((SELECT count(*)=0 FROM public.edupulse_material_progress),'another instructor cannot read progress');
SELECT pg_temp.monitoring_as('admin');
SELECT pg_temp.monitoring_assert(jsonb_array_length(public.edupulse_support_action((SELECT id FROM monitoring_canary_ids WHERE kind='instructor'),'academic.read','{}')->'reading')=1,'selected-instructor support sees authorized progress');
DO $$ BEGIN BEGIN PERFORM public.edupulse_support_action((SELECT id FROM monitoring_canary_ids WHERE kind='learner'),'academic.command',jsonb_build_object('operation','read-section','publication',(SELECT id FROM monitoring_canary_publications WHERE type='material'),'version',(SELECT source_version FROM monitoring_canary_publications WHERE type='material'),'section',0)); RAISE EXCEPTION 'Support fabricated learner reading'; EXCEPTION WHEN insufficient_privilege THEN NULL; END; END $$;
SELECT pg_temp.monitoring_as('instructor');
UPDATE monitoring_canary_state SET data=jsonb_set(jsonb_set(data,'{enrollmentOverrides,0,excluded}','true'),'{registrations}','[]');
SELECT public.edupulse_save_workspace(3,data) FROM monitoring_canary_state;
SELECT pg_temp.monitoring_assert((SELECT count(*)=0 FROM public.edupulse_enrollments),'suspended membership removed');
SELECT pg_temp.monitoring_assert((SELECT count(*)=1 FROM public.edupulse_material_progress),'reading history retained');
SELECT pg_temp.monitoring_assert((SELECT count(*)=1 FROM public.edupulse_attempts),'assessment history retained');
RESET ROLE;
ROLLBACK;
SELECT 'passed rolled-back suspension, sequential reading, retained score/history and scoped support canary' AS validation;
